const r = await tools.exec_command({cmd:"python3 - <<'PY'
import json, re, pathlib, statistics
for p in sorted(pathlib.Path('outputs/val_generations').glob('*.jsonl')):
    rows=[json.loads(x) for x in p.open()]
    def corr(r):
      nums=re.findall(r'####\s*([-+]?\d+(?:\.\d+)?)', r.get('output',''))
      return bool(nums) and float(nums[-1])==float(r.get('gts'))
    print(p, len(rows), 'stored_score',sum(r.get('score',0) for r in rows), 'delimiter',sum(bool(re.findall(r'####\s*[-+]?\d+(?:\.\d+)?',r.get('output',''))) for r in rows), 'grader',sum(corr(r) for r in rows), 'acc',sum(corr(r) for r in rows)/len(rows))
    # output lengths and missing markers
    ls=[len(r.get('output','')) for r in rows]
    print('len',statistics.mean(ls),min(ls),max(ls),'reward',statistics.mean([r.get('reward',0) for r in rows]), 'first outputs missing',sum(not re.findall(r'####\s*[-+]?\d+(?:\.\d+)?',r.get('output','')) for r in rows))
