const r = await tools.exec_command({cmd:"python3 - <<'PY'
import json,re,statistics
rows=[json.loads(x) for x in open('outputs/val_generations/0.jsonl')]
# heuristic: capture last numeric token, preferably after final/answer/is/boxed or last number
patterns=[
 r'####\s*\$?([\d,]+(?:\.\d+)?)',
 r'boxed\{\s*\$?([\d,]+(?:\.\d+)?)',
 r'(?:final answer|answer is|therefore[^\n]*|so,?[^\n]*answer[^\n]*)[^\d$-]*\$?(-?[\d,]+(?:\.\d+)?)',
]
def nums(s): return re.findall(r'(?<![\w])\$?(-?\d[\d,]*(?:\.\d+)?)',s)
for idx,pat in enumerate(patterns):
 n=0; present=0
 for r in rows:
  ms=re.findall(pat,r['output'],re.I)
  if ms:
   present+=1
   try:
    if float(ms[-1].replace(',',''))==float(r['gts']):n+=1
   except:pass
 print(idx,present,n,n/len(rows))
# last num overall
n=0
for r in rows:
 ms=nums(r['output'])
 if ms:
  try:n+=float(ms[-1].replace(',',''))==float(r['gts'])
  except:pass
print('last number',n,n/len(rows))
PY","workdir":"/workspace","yield_time_ms":10000,"max_output_tokens":10000});
text(r.output);

